/* Uni Explorer v2.0: SPA autocontenida, sin backend ni navegación de URL. */
(()=>{'use strict';
 const raw={ehu:window.EHU_DATA,upna:window.UPNA_DATA,deusto:window.DEUSTO_DATA,navarra:window.NAVARRA_DATA,mondragon:window.MONDRAGON_DATA,euneiz:window.EUNEIZ_DATA,uned:window.UNED_DATA};
 const main=document.getElementById('main'),popup=document.getElementById('hover-popover');
 const RAMAS=['Artes y Humanidades','Ciencias','Ciencias de la Salud','Ciencias Sociales y Jurídicas','Ingeniería y Arquitectura'];
 const CFG={upna:{name:'UPNA · Universidad Pública de Navarra',short:'UPNA',campuses:['Pamplona','Tudela'],type:'Pública',website:'https://www.unavarra.es/sites/estudios/'},ehu:{name:'EHU · Universidad del País Vasco',short:'EHU',campuses:['Araba','Gipuzkoa','Bizkaia'],type:'Pública',website:'https://www.ehu.eus/es/web/graduak/graduak'},deusto:{name:'Universidad de Deusto',short:'Deusto',campuses:['Bilbao','Donostia-San Sebastián'],type:'Privada',website:'https://www.deusto.es/es/inicio/estudia/estudios/grados'},navarra:{name:'Universidad de Navarra',short:'Universidad de Navarra',campuses:['Pamplona','Donostia-San Sebastián'],type:'Privada',website:'https://www.unav.edu/estudios/grados'}};
 CFG.mondragon={name:'Mondragon Unibertsitatea',short:'Mondragon',campuses:[...(raw.mondragon?.meta.campus||['Arrasate-Mondragón','Goierri (Ordizia)','Hernani (Galarreta)','Oñati','Irun (Bidasoa)','Bilbao','Eskoriatza','Aretxabaleta','Donostia-San Sebastián']),...(raw.mondragon?.meta.laboratorios_leinn||[])],type:'Privada',website:'https://www.mondragon.edu/es/grados-universitarios'};
 CFG.euneiz={name:'EUNEIZ',short:'EUNEIZ',campuses:['Vitoria-Gasteiz'],type:'Privada',website:'https://www.euneiz.com/grados-universitarios/'};
 CFG.uned={name:'UNED',short:'UNED',campuses:['A distancia'],type:'Pública · a distancia',website:'https://www.uned.es/universidad/inicio/estudios/grados.html'};
 const unedCenters=[
  ['Vitoria-Gasteiz','https://www.uned.es/universidad/centros/vitoria-gasteiz.html'],
  ['Bizkaia','https://www.uned.es/universidad/centros/bizkaia.html'],
  ['Bergara','https://www.uned.es/universidad/centros/bergara.html'],
  ['Pamplona','https://www.uned.es/universidad/centros/pamplona.html'],
  ['Tudela','https://www.uned.es/universidad/centros/tudela.html']
 ];
 const norm=x=>String(x??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').replace(/\s+/g,' ').trim();
 const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const sortText=(a,b)=>String(window.UniI18n?.text(a)??a??'').localeCompare(String(window.UniI18n?.text(b)??b??''),window.UniI18n?.locale||'es',{sensitivity:'base'});
 const num=(n,d=2)=>typeof n==='number'&&Number.isFinite(n)?new Intl.NumberFormat(window.UniI18n?.locale||'es-ES',{maximumFractionDigits:d,minimumFractionDigits:0}).format(n):'—';
 const eur=(n,d=0)=>typeof n==='number'&&Number.isFinite(n)?new Intl.NumberFormat(window.UniI18n?.locale||'es-ES',{style:'currency',currency:'EUR',useGrouping:'always',minimumFractionDigits:d,maximumFractionDigits:d}).format(n):'No consta';
 const validUrl=x=>typeof x==='string'&&/^https:\/\//.test(x)?x:null;
 const link=(x,label)=>validUrl(x)?`<a href="${safe(x)}" target="_blank" rel="noopener noreferrer">${safe(label)}</a>`:'';
 const pill=(x,cls='')=>`<span class="pill ${cls}">${safe(x)}</span>`;
 const degreeKey=g=>norm(g.nombre_corto||g.titulacion).replace(/\s*\((?:plan nuevo|nuevo plan \d{4}|euskera|trilingue)\)\s*/g,'');
 const datasets={};
 for(const uni of Object.keys(CFG)){
   const src=raw[uni]||{}, pmap=new Map();
   if(uni==='upna')for(const g of src.grados||[]){if(!pmap.has(g.id_ponderacion))pmap.set(g.id_ponderacion,g.ponderaciones||[])}
    if(uni==='ehu')for(const p of src.ponderaciones||[]){if(p.coeficiente!==0.1&&p.coeficiente!==0.2)continue;const k=String(p.grado_ponderacion||'');if(!pmap.has(k))pmap.set(k,[]);pmap.get(k).push(p)}
   const records=(src.grados||[]).filter(g=>uni!=='ehu'||g.oferta_2026).filter(g=>CFG[uni].campuses.includes(g.campus)).filter(g=>uni!=='deusto'||g.estado_oferta!=='Inicio 2027-2028').map(g=>({...g,precio_primero:g.precio_primero??g.precio_primero_2026??null,coste_total_est:g.coste_total_est??g.coste_total_est_2026??null,url_grado:g.url_grado||window.ORIENTATION_DATA?.guides?.[uni]?.[degreeKey(g)]?.source?.url||null}));
   const groups=new Map();for(const g of records){const k=degreeKey(g);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(g)}
   const arr=[...groups.entries()].map(([key,offers],i)=>({key,offers,id:`${uni}--${i}`,name:chooseName(offers)})).sort((a,b)=>sortText(window.UniI18n?.degree(uni,a.key,a.name)||a.name,window.UniI18n?.degree(uni,b.key,b.name)||b.name));
   datasets[uni]={src,records,groups:arr,lookup:new Map(arr.map(g=>[g.id,g])),pmap};
 }
 function priceCourse(uni){return datasets[uni]?.src.meta?.curso_precio||'2026–2027'}
 function priceYear(g,uni=state.uni){return g.curso_precio||g.precio_curso||priceCourse(uni)}
 function campusTiles(uni,counts){const cfg=CFG[uni],tile=c=>`<button type="button" data-open-campus="${safe(c)}" class="route-tile"><span class="route-arrow">↗</span><b>${safe(c)}</b><small>${counts[c]} ofertas</small></button>`;if(uni!=='mondragon')return cfg.campuses.map(tile).join('');const labs=cfg.campuses.filter(c=>c.startsWith('LEINN · '));return cfg.campuses.filter(c=>!c.startsWith('LEINN · ')).map(tile).join('')+(labs.length?`<details class="mu-labs"><summary>Otras sedes de la red LEINN · ${labs.length}</summary><p>Laboratorios desarrollados con entidades colaboradoras; consulta sus modalidades, condiciones y título expedido.</p><div class="campus-links">${labs.map(tile).join('')}</div></details>`:'')}
 function chooseName(offers){const title=offers.map(o=>o.titulacion).find(x=>!/\((?:plan nuevo|nuevo plan \d{4}|euskera|trilingüe)\)/i.test(x));return title||offers[0].titulacion;}
 const materiasByUni=Object.fromEntries(['ehu','upna'].map(uni=>{const rows=uni==='upna'?(raw.upna?.grados||[]).flatMap(g=>g.ponderaciones||[]):(raw.ehu?.ponderaciones||[]);return [uni,[...new Set(rows.filter(p=>p.coeficiente===0.1||p.coeficiente===0.2).map(p=>p.materia))].sort(sortText)];}));
  const isPublic=uni=>uni==='ehu'||uni==='upna';
  const materias=()=>materiasByUni[state.uni]||[];
 const initial=()=>({screen:'portal',uni:null,campus:'',rama:'',materia:'',facultad:'',q:'',sort:'name',searchText:'',detailTab:'ficha',statusFilter:'all',shortlistFilter:'all'});
 const browserHistory=window.history;
 const savedRoute=browserHistory.state;
 const isAppRoute=entry=>entry?.uniExplorer===true&&entry.screenState&&['portal','university','campus','rama','subject','detail','favorites','compare'].includes(entry.screenState.screen)&&(entry.screenState.uni===null||Object.hasOwn(CFG,entry.screenState.uni));
 let state=isAppRoute(savedRoute)?{...initial(),...savedRoute.screenState}:initial(),navigationIndex=isAppRoute(savedRoute)?savedRoute.index||0:0;
 const historyEntry=scroll=>({uniExplorer:true,screenState:{...state},scroll,index:navigationIndex});
 browserHistory.scrollRestoration='manual';
 browserHistory.replaceState(historyEntry(isAppRoute(savedRoute)?savedRoute.scroll||0:0),'');
 const favoriteOrder=['ehu','upna','deusto','navarra','mondragon','euneiz','uned'];
 const shortlistIcon=window.UniFavorites.icon('selected');
 const compactPopover=()=>window.matchMedia('(max-width: 690px), (hover: none)').matches;
 function subjectBook(group,uni=state.uni){return group&&isPublic(uni)?`<button class="subject-book" type="button" data-subject-book="${safe(group.id)}" data-book-uni="${safe(uni)}" aria-label="Ver ponderaciones: ${safe(group.name)}" aria-haspopup="dialog" aria-expanded="false"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v15"/></svg></button>`:'';}
 function favoriteButtonContent(value){
  const caption=value==='none'?'Marcar interés':window.UniFavorites.states[value].label;
  return window.UniFavorites.icon(value)+'<span class="interest-button-label">'+safe(caption)+'</span>';
 }
 function favoriteButton(group,uni=state.uni){if(!group)return'';const value=window.UniFavorites.status(uni,group.key),label='Cambiar interés: '+group.name+' · '+window.UniFavorites.states[value].label;return `<button type="button" class="favorite-button status-${value}" data-favorite="${safe(group.id)}" data-favorite-uni="${safe(uni)}" aria-haspopup="dialog" aria-label="${safe(label)}" title="${safe(label)}">${favoriteButtonContent(value)}</button>`;}
 function selectionFilterHTML(shortlist=false){const value=shortlist?state.shortlistFilter:state.statusFilter,values=shortlist?['all','doubt','selected']:['all','none','doubt','selected','rejected'];return `<div class="field selection-filter-field"><label for="selection-filter">Estado de interés</label><select id="selection-filter">${values.map(v=>'<option value="'+v+'"'+(value===v?' selected':'')+'>'+(v==='all'?'Todos':window.UniFavorites.states[v].label)+'</option>').join('')}</select></div>`;}
 function interestMatches(group,uni,value){return value==='all'||window.UniFavorites.status(uni,group.key)===value;}
 function shortlistGroups(){return favoriteGroups().filter(({uni,group})=>interestMatches(group,uni,state.shortlistFilter));}
 function favoriteGroups(){return favoriteOrder.flatMap(uni=>datasets[uni].groups.filter(g=>window.UniFavorites.has(uni,g.key)).map(group=>({uni,group})));}
 function favoritesPortal(){const n=favoriteGroups().length;return n?`<section class="favorites-portal"><div class="portal-label">Tu selección</div><button type="button" class="favorites-entry" data-action="favorites"><span class="favorites-entry-icon" aria-hidden="true">${shortlistIcon}</span><span><strong>Carreras seleccionadas</strong><small>${n} ${n===1?'carrera':'carreras'} · Las que te interesan y las que tienes en duda</small></span><span aria-hidden="true">→</span></button></section>`:'';}
 function renderFavorites(){const groups=shortlistGroups(),total=favoriteGroups().length;main.innerHTML=`${top('Tu selección','Carreras seleccionadas','Las carreras que te interesan y las que tienes en duda, agrupadas por universidad. Puedes cambiar de opinión en cualquier momento.')}<div class="favorites-toolbar"><span>${groups.length} ${groups.length===1?'carrera':'carreras'}${groups.length!==total?' de '+total:''}</span>${selectionFilterHTML(true)}<div><button class="primary-button" type="button" data-action="export-favorites"${groups.length?'':' disabled'}>Exportar CSV · Excel</button><button class="profile-cancel" type="button" data-action="print-favorites"${groups.length?'':' disabled'}>Imprimir / guardar PDF</button></div></div><p class="favorites-export-note">Se exporta la selección mostrada, incluyendo su estado de interés. CSV: una fila por oferta de campus. Para PDF, elige «Guardar como PDF» al imprimir.</p>${groups.length?favoriteOrder.map(uni=>{const selected=groups.filter(x=>x.uni===uni);return selected.length?`<section class="favorites-university"><h2>${safe(CFG[uni].name)} <small>${selected.length}</small></h2><div class="results-list">${selected.map(({group})=>rowHTML(group.offers[0],uni,group,true)).join('')}</div></section>`:'';}).join(''):total?'<div class="empty-panel"><b>No hay carreras con este estado.</b>Selecciona «Todos» para ver las que te interesan y las que están en duda.</div>':'<div class="empty-panel"><b>Aún no tienes carreras seleccionadas.</b>Pulsa el icono de interés de una carrera y elige «Me interesa» o «En duda» para añadirla aquí.</div>'}`;}
 function exportFavorites(){const csvNumber=n=>typeof n==='number'&&Number.isFinite(n)?String(n).replace('.',','):'';const favorites=shortlistGroups();if(!favorites.length)return;const rows=[['Universidad','Carrera','Estado de interés','Campus','Centro','Rama','ECTS','Duración (años)','Nota 2025','Nota 2026','Curso de precios','Precio primero (€)','Coste total estimado (€)','Compatibilidad con mi perfil','Web carrera']];for(const {uni,group} of favorites){const status=isPublic(uni)?profileStatus(group,uni):null;for(const g of group.offers)rows.push([CFG[uni].name,window.UniI18n?.degree(uni,group.key,g.titulacion)||g.titulacion,window.UniFavorites.states[window.UniFavorites.status(uni,group.key)].label,g.campus,g.centro,g.rama,csvNumber(g.ects),csvNumber(g.anos),csvNumber(g.nota_2025),csvNumber(g.nota_2026),priceYear(g,uni),csvNumber(g.precio_primero),csvNumber(g.coste_total_est),status?status.label+' (máximo teórico)':'',g.url_grado||g.fuente_oferta||CFG[uni].website]);}const blob=new Blob([window.UniFavorites.csv(rows)],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=window.UniI18n?.lang==='eu'?'uni-explorer-hautatutako-karrerak.csv':'uni-explorer-carreras-seleccionadas.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 let favoriteNoticeTimer=null;
 function favoriteNotice(message){const el=document.getElementById('favorite-notice');clearTimeout(favoriteNoticeTimer);el.textContent=message;el.hidden=false;favoriteNoticeTimer=setTimeout(()=>{el.hidden=true;},4000);}
 function refreshFavorites(){hidePopup();if(state.screen==='portal')renderPortal();else if(state.screen==='favorites')renderFavorites();else if(['campus','rama','subject'].includes(state.screen))updateList();else if(state.screen==='university')updateSuggestions();else document.querySelectorAll('[data-favorite]').forEach(button=>{const uni=button.dataset.favoriteUni,group=datasets[uni]?.lookup.get(button.dataset.favorite);if(!group)return;const value=window.UniFavorites.status(uni,group.key),label='Cambiar interés: '+group.name+' · '+window.UniFavorites.states[value].label;button.className='favorite-button status-'+value;button.innerHTML=favoriteButtonContent(value);button.setAttribute('aria-label',label);button.title=label;});}
 function saveHistory(){browserHistory.replaceState(historyEntry(window.scrollY||0),'');}
 function go(screen,patch={}){hidePopup();saveHistory();state={...state,...patch,screen};navigationIndex++;browserHistory.pushState(historyEntry(0),'');render();window.scrollTo(0,0);}
 function goBack(){saveHistory();if(navigationIndex>0)browserHistory.back();else if(state.screen!=='portal')go('portal',initial());}
 window.addEventListener('popstate',e=>{if(!isAppRoute(e.state))return;state={...initial(),...e.state.screenState};navigationIndex=e.state.index||0;const scroll=e.state.scroll||0;render();requestAnimationFrame(()=>window.scrollTo(0,scroll));});
 window.addEventListener('scroll',()=>{if(isAppRoute(browserHistory.state))saveHistory();},{passive:true});
 function chooseUni(uni){go('university',{uni,campus:'',rama:'',materia:'',facultad:'',q:'',sort:'name',searchText:'',statusFilter:'all'})}
 const backBtn=()=>`<button class="back-button" type="button" data-action="back">← Volver</button>`;
 function top(label,heading,description){return `<div class="page-top">${backBtn()}<div class="eyebrow">${safe(label)}</div><h1>${safe(heading)}</h1><p>${safe(description)}</p></div>`}
 function renderPortal(){
  const card=(id,ordinal,category,headline,place,summary)=>`<button class="portal-card" data-uni="${id}" type="button"><span class="portal-logo-wrap"><img class="portal-logo" src="${universityLogo(id)}" alt="" aria-hidden="true" width="180" height="72"></span><span class="portal-number">${ordinal} · ${category}</span><h2>${headline}</h2><strong>${place}</strong><p>${summary}</p><span class="portal-cta">Explorar grados <span aria-hidden="true">→</span></span></button>`;
  main.innerHTML=`<section class="hero portal-hero"><div class="eyebrow">Guía universitaria · cursos y precios identificados</div><h1>¿Qué universidad quieres explorar?</h1><p>Busca grados, compara campus y centros, consulta los requisitos académicos y examina los costes cuando están publicados.</p></section>
  <div class="compare-entry"><button type="button" class="primary-button" data-action="compare">⇄ <span>Comparador de carreras</span></button></div>
  ${favoritesPortal()}<div class="portal-label">Universidades públicas</div><div class="portal-grid portal-private">${card('ehu','01','Pública','EHU · Universidad del País Vasco','Araba, Gipuzkoa y Bizkaia','Notas de corte de 2025 y 2026; materias de Bachillerato que ponderan 0,1 o 0,2.')}${card('upna','02','Pública','UPNA · Universidad Pública de Navarra','Pamplona y Tudela','Notas de corte 2025 y 2026, materias que ponderan y su fase de evaluación.')}</div>
  <div class="portal-label">Universidades privadas</div><div class="portal-grid portal-private">${card('deusto','03','Privada','Deusto','Campus de Bilbao y Donostia','Grados, facultades, precios oficiales de primero y costes totales orientativos.')}${card('navarra','04','Privada','Universidad de Navarra','Pamplona y Tecnun · Donostia','Grados, programas combinados, precios de primero y costes totales orientativos.')}${card('mondragon','05','Privada','Mondragon Unibertsitatea','9 ubicaciones en Euskadi y red LEINN','Ingenierías, empresa, educación, cultura y gastronomía. Precios previstos 2027–2028 y fichas de orientación.')}${datasets.euneiz?card('euneiz','06','Privada','EUNEIZ','Vitoria-Gasteiz','Salud, deporte y tecnologías interactivas. Consulta plazas, admisión y precios.'):''}</div>
  ${datasets.uned?`<div class="portal-label">Universidades a distancia</div><div class="portal-grid">${card('uned','07','Pública · a distancia','UNED','Centros asociados en Euskadi y Navarra','Grados a distancia, precios públicos y centros de apoyo para tutorías, exámenes y prácticas.')}</div>`:''}
  <div class="helper-note"><span class="notice-symbol">ⓘ</span><span>Deusto y Universidad de Navarra: tarifas <strong>2026–2027</strong>. Mondragon: precios previstos <strong>2027–2028</strong>, provisionales. Consulta el curso en cada ficha. Los costes totales son extrapolaciones que no contemplan subidas posteriores, becas, alojamiento ni manutención. Las universidades públicas utilizan sus propias ponderaciones oficiales; no se aplican a las privadas.</span></div>`;
 }
 function renderCompare(){
  const title='Comparador de carreras';
   const controls=[0,1].map(i=>'<div class="section-card compare-choice"><label for="compare-query-'+i+'">Opción '+(i+1)+'</label><div class="compare-combobox"><input id="compare-query-'+i+'" type="search" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="compare-options-'+i+'" autocomplete="off" placeholder="Universidad, campus o carrera"><ul id="compare-options-'+i+'" role="listbox" aria-label="Opción '+(i+1)+'" class="compare-options" hidden></ul></div></div>').join('');
  main.innerHTML=top(title,title,'Busca por universidad, campus o carrera y elige dos ofertas distintas.')+
   '<div class="compare-controls">'+controls+'<button class="primary-button" type="button" id="compare-run" disabled><span aria-hidden="true">⇄</span> <span>Comparar</span></button></div><section id="comparison-result" aria-live="polite"></section>';
  const offers=Object.entries(datasets).flatMap(([uni,ds])=>ds.records.map(offer=>{
   const key=degreeKey(offer);
   return {uni,key,offer,groupId:groupedForRow(offer,uni)?.id,weights:pondSets({offers:[offer]},uni).flatMap(set=>set.items),name:uni==='navarra'?'UN':CFG[uni].short,fullName:CFG[uni].name,title:window.UniI18n?.degree(uni,key,offer.titulacion)||offer.titulacion};
  }));
  window.UniCompare.mount(main,offers,state.comparison,comparison=>{state.comparison=comparison;saveHistory();});
 }
 const universityLogo=id=>`assets/logos/${id}.${['deusto','mondragon','uned'].includes(id)?'png':'svg'}`;
 function filterTop(uni,heading,description){
  const logo='<img class="filter-page-logo" data-logo-uni="'+safe(uni)+'" src="'+universityLogo(uni)+'" alt="'+safe(CFG[uni].name)+'">';
  const name=heading?logo:'<h1>'+logo+'</h1>';
  return '<div class="page-top filter-page-top"><div class="filter-page-nav">'+backBtn()+name+'</div>'+
   (heading?'<h1>'+safe(heading)+'</h1>':'')+'<p>'+safe(description)+'</p></div>';
 }
 function renderUniversity(){
  const {uni}=state,cfg=CFG[uni],ds=datasets[uni],isE=isPublic(uni),counts=Object.fromEntries(cfg.campuses.map(c=>[c,ds.records.filter(g=>g.campus===c).length]));
  main.innerHTML=`${filterTop(uni,'','Busca una titulación o explora el catálogo por campus y rama de conocimiento.')}
  <div class="home-grid">
  <section class="panel panel-wide"><div class="panel-tag">01 · Buscador</div><h2>Buscar una carrera</h2><p>Escribe al menos 3 caracteres. Si un grado se imparte en varios campus, el buscador lo mostrará una sola vez.</p><div class="search-wrap" id="search-wrap"><div class="search-control"><span class="search-icon">⌕</span><input id="degree-search" type="search" role="combobox" aria-expanded="false" aria-controls="search-suggestions" autocomplete="off" placeholder="Ej. Medicina, Derecho, Ingeniería…" value="${safe(state.searchText)}"></div><div id="search-suggestions" class="suggestions" role="listbox" hidden></div></div><div class="search-hint">Ignora mayúsculas y tildes · Mínimo 3 letras</div></section>
  <section class="panel panel-wide"><div class="panel-tag">02 · Ramas</div><h2>Rama de conocimiento</h2><p>Cinco categorías para filtrar las ofertas. En las privadas, la clasificación es orientativa cuando no se ha verificado la rama oficial de la titulación.</p><div class="theme-links branch-links">${RAMAS.map((r,i)=>`<button class="theme-card" type="button" data-open-rama="${safe(r)}"><span class="theme-illustration">${['Aa','∑','✚','§','⌘'][i]}</span><b>${safe(r)}</b><small>${ds.records.filter(g=>g.rama===r).length} ofertas</small></button>`).join('')}</div></section>
  <section class="panel panel-wide"><div class="panel-tag">03 · Campus</div><h2>${uni==='uned'?'Oferta a distancia':uni==='mondragon'?'Explorar por campus y sedes':'Explorar por campus'}</h2><p>En los listados puedes filtrar por facultad, ordenar resultados${isE?' y seleccionar una materia que pondera':''}.</p><div class="campus-links">${campusTiles(uni,counts)}</div></section>
  ${uni==='uned'?`<section class="panel panel-wide"><h2>Centros asociados</h2><p>Consulta en cada centro qué tutorías, exámenes y prácticas ofrece para tu grado.</p><div class="sources-list">${unedCenters.map(([name,url])=>link(url,name)).join('')}</div></section>`:''}
  ${isE?`<section class="panel panel-wide"><div class="panel-tag">04 · Ponderaciones</div><h2>¿Dónde pondera una asignatura?</h2><p>Elige una materia, por ejemplo Biología, para ver exclusivamente los grados en que se aplica un coeficiente de 0,1 o 0,2.</p><div class="subject-lookup"><select id="home-materia" aria-label="Asignatura de Bachillerato"><option value="">Seleccionar asignatura…</option>${materiaOptions('')}</select><button type="button" class="primary-button" data-action="search-subject">Ver carreras</button></div></section>`:uni==='uned'?`<div class="helper-note">Consulta los requisitos de admisión de cada grado. Los exámenes y algunas prácticas pueden requerir asistencia presencial.</div>`:`<div class="helper-note private-hint"><span class="notice-symbol">€</span><span>Las universidades privadas no publican una tabla de ponderaciones equivalente a la EHU en este conjunto de datos. En sus fichas se muestran el importe oficial de primero y una estimación de toda la carrera cuando están disponibles.</span></div>`}
  </div><div class="helper-note"><span class="notice-symbol">ⓘ</span><span>${isE?uni==='upna'?'UPNA: notas de corte de la última lista de cada curso; las cifras de primera adjudicación se conservan en el Excel y JSON. Parámetros oficiales específicos de la UPNA.':'Las notas 2025 y 2026 pueden proceder de distintas fases de admisión; no siempre son comparables. Cuando una ponderación no puede relacionarse con una carrera, se indica expresamente.':'Los importes de primero proceden de las tablas publicadas '+priceCourse(uni)+'. La estimación total conserva los precios de ese curso; no es un presupuesto ni refleja las tasas de cursos superiores.'}</span></div>`;
  updateSuggestions();
 }
 function materiaOptions(selected){return materias().map(m=>`<option value="${safe(m)}"${m===selected?' selected':''}>${safe(m)}</option>`).join('')}
 function updateSuggestions(){
  if(state.screen!=='university')return;
  const input=document.getElementById('degree-search'),sug=document.getElementById('search-suggestions');if(!input||!sug)return;
  state.searchText=input.value;saveHistory();const t=norm(input.value);if(t.length<3){sug.hidden=true;sug.innerHTML='';input.setAttribute('aria-expanded','false');return}
  const matches=datasets[state.uni].groups.filter(g=>norm(window.UniI18n?.searchName(state.uni,g.key,g.name)||g.name).includes(t)||g.offers.some(o=>norm(window.UniI18n?.searchName(state.uni,degreeKey(o),o.titulacion)||o.titulacion).includes(t))).slice(0,20);
  sug.innerHTML=matches.length?matches.map((g,i)=>`<div class="suggestion-row" data-hover-group="${safe(g.id)}" data-hover-uni="${safe(state.uni)}"><button type="button" role="option" data-open-detail="${g.id}" class="suggestion ${i===0?'active':''}" aria-selected="${i===0?'true':'false'}">${profileMarker(g)}<span><b class="degree-search-name"><span data-degree-name>${safe(g.name)}</span></b><small>${safe([...new Set(g.offers.map(o=>o.campus))].join(' · '))}</small></span><span class="arrow">→</span></button>${subjectBook(g)}${favoriteButton(g)}</div>`).join(''):'<div class="suggestions-empty">No se han encontrado grados con ese texto.</div>';
  sug.hidden=false;input.setAttribute('aria-expanded','true');
 }
 function pondSets(g,uni=state.uni){if(!isPublic(uni))return[];const ids=[...new Set(g.offers.flatMap(x=>uni==='ehu'?String(x.ponderacion_ids||'').split('|').filter(Boolean):[x.id_ponderacion].filter(Boolean)))];return ids.map(id=>({id,items:datasets[uni].pmap.get(id)||[]})).filter(x=>x.items.length)}
 function pondContains(g,mat){return !!pondSets(g).some(s=>s.items.some(x=>norm(x.materia)===norm(mat)))}
 function groupedForRow(g,uni=state.uni){return datasets[uni].groups.find(gr=>gr.offers.includes(g))}
 function selectOptions(items,value){return items.map(x=>`<option value="${safe(x)}" ${x===value?'selected':''}>${safe(x)}</option>`).join('')}
 function renderList(){
  const {uni,screen}=state, ds=datasets[uni], cfg=CFG[uni];const isCampus=screen==='campus';const isRama=screen==='rama';const isSubject=screen==='subject';const base=ds.records.filter(r=>isCampus?r.campus===state.campus:isRama?r.rama===state.rama:true);
  const centers=[...new Set(base.map(r=>r.centro).filter(Boolean))].sort(sortText), campuses=[...new Set(base.map(r=>r.campus))].sort(sortText);
  const header=isCampus?state.campus:isRama?state.rama:`Materias: ${state.materia||'Seleccionar asignatura'}`;
  main.innerHTML=`${filterTop(uni,header,isCampus?(isPublic(uni)?'Grados del campus. Filtra por centro, ordena por nota o nombre y consulta las ponderaciones sobre el nombre o con el libro en móvil.':'Grados del campus. Filtra por centro y ordena por nombre o precio.'):isRama?'Titulaciones de esta rama, con filtros y ordenación.':'Carreras para las que la materia seleccionada pondera en '+cfg.short+'.')}
  <div class="filter-bar filter-bar-extended">
   ${isCampus?`<div class="field"><label for="faculty-filter">Facultad / Escuela</label><select id="faculty-filter"><option value="">Todos los centros</option>${selectOptions(centers,state.facultad)}</select></div>`:`<div class="field"><label for="campus-filter">Campus</label><select id="campus-filter"><option value="">Todos los campus</option>${selectOptions(campuses,state.campus)}</select></div>`}
   <div class="field"><label for="list-query">Buscar carrera o centro</label><input id="list-query" type="search" placeholder="Buscar…" value="${safe(state.q)}"></div>
   ${isPublic(uni)?`<div class="field"><label for="materia-filter">Asignatura que pondera</label><select id="materia-filter"><option value="">Todas las asignaturas</option>${materiaOptions(state.materia)}</select></div>`:''}
   <div class="field"><label for="sort-by">Ordenar por</label><select id="sort-by"><option value="name" ${state.sort==='name'?'selected':''}>Nombre · A → Z</option><option value="faculty" ${state.sort==='faculty'?'selected':''}>Facultad · A → Z</option>${isPublic(uni)?`<option value="note2026" ${state.sort==='note2026'?'selected':''}>Nota 2026 · Mayor a menor</option><option value="note2025" ${state.sort==='note2025'?'selected':''}>Nota 2025 · Mayor a menor</option>`:`<option value="firstprice" ${state.sort==='firstprice'?'selected':''}>Precio de 1.º · Menor a mayor</option><option value="totalprice" ${state.sort==='totalprice'?'selected':''}>Coste estimado · Menor a mayor</option>`}</select></div>
   ${selectionFilterHTML()}<span class="filter-count" id="filter-count"></span></div>
   <div class="data-summary"><span class="small">${isPublic(uni)?'Nota de corte de cupo general, solo donde publicada. Popover de materias al pasar sobre cada carrera.':'Tarifas '+priceCourse(uni)+(uni==='mondragon'?' · importes provisionales.':'')+' Estimaciones orientativas.'}</span><button type="button" class="btn-text" data-action="reset-filters">Restablecer filtros</button></div>
   ${isPublic(uni)&&window.UniProfile?.get()?'<div class="profile-legend"><span><i class="compat-dot green"></i> Hasta 14</span><span><i class="compat-dot blue"></i> Entre 10 y 14</span><span><i class="compat-dot red"></i> Hasta 10</span><small>Máximos teóricos con tus materias. Verde también si no hay ponderaciones en los datos: consulta el detalle.</small></div>':''}<div id="results-list" class="results-list"></div>`;
  updateList();
 }
 function updateList(){
  const {screen,uni}=state,ds=datasets[uni];let entries=ds.records.filter(g=>screen==='campus'?g.campus===state.campus:screen==='rama'?g.rama===state.rama:true);
  if(screen!=='campus'&&state.campus)entries=entries.filter(g=>g.campus===state.campus);
  if(state.statusFilter!=='all')entries=entries.filter(g=>{const group=groupedForRow(g);return group&&interestMatches(group,uni,state.statusFilter)});
  if(state.facultad)entries=entries.filter(g=>g.centro===state.facultad);
  if(state.materia&&isPublic(uni))entries=entries.filter(g=>{let group=groupedForRow(g);return group?pondContains(group,state.materia):false});
  if(state.q)entries=entries.filter(g=>norm([window.UniI18n?.searchName(state.uni,degreeKey(g),g.titulacion)||g.titulacion,window.UniI18n?.searchText(g.centro)||g.centro,window.UniI18n?.searchText(g.campus)||g.campus].join(' ')).includes(norm(state.q)));
  const sorter={name:(a,b)=>sortText(window.UniI18n?.degree(uni,degreeKey(a),a.titulacion)||a.titulacion,window.UniI18n?.degree(uni,degreeKey(b),b.titulacion)||b.titulacion)||sortText(a.campus,b.campus),faculty:(a,b)=>sortText(a.centro,b.centro)||sortText(a.titulacion,b.titulacion),};
  // Los datos ausentes deben ir siempre al final independientemente del orden.
  const key=state.sort;
  if(['note2025','note2026'].includes(key)){const fld=key==='note2025'?'nota_2025':'nota_2026';entries.sort((a,b)=>nullableCompare(a,b,fld,true)||sortText(a.titulacion,b.titulacion));}
  else if(['firstprice','totalprice'].includes(key)){const fld=key==='firstprice'?'precio_primero':'coste_total_est';entries.sort((a,b)=>nullableCompare(a,b,fld,false)||sortText(a.titulacion,b.titulacion));}
  else entries.sort(sorter[key]||sorter.name);
  document.getElementById('filter-count').textContent=`${entries.length} ${entries.length===1?'oferta':'ofertas'}`;
  document.getElementById('results-list').innerHTML=entries.length?entries.map(g=>rowHTML(g)).join(''):'<div class="empty-panel"><b>No hay resultados.</b>Modifica o limpia los filtros para ampliar la búsqueda.</div>';
  saveHistory();
 }
 
 function nullableCompare(a,b,field,desc){const av=a[field],bv=b[field],aOk=typeof av==='number',bOk=typeof bv==='number';if(aOk!==bOk)return aOk?-1:1;if(!aOk)return 0;return desc?bv-av:av-bv}
 function noteMini(g,y){const n=g[`nota_${y}`],st=g[`estado_${y}`];return `<div class="year-note" title="${safe(st||'No publicada')}"><small>${y}</small><b class="${typeof n==='number'?'':'empty'}">${typeof n==='number'?num(n,3):st==='Plazas vacantes'?'Vacantes':'—'}</b></div>`}
 function profileStatus(group,uni=state.uni){return window.UniProfile?.assess(pondSets(group,uni),window.UniProfile.get(),uni)}
 function profileMarker(group,uni=state.uni){const s=group&&isPublic(uni)?profileStatus(group,uni):null;return s?`<span class="compat-dot ${s.color}" role="img" aria-label="${safe(s.label)}" title="${safe(s.label)}"></span>`:''}
 function rowHTML(g,uni=state.uni,selectedGroup=null,allCampuses=false){const group=selectedGroup||groupedForRow(g,uni),isE=isPublic(uni);return `<article class="degree-row ${isE?'hoverable':''}" data-open-detail="${safe(group?.id||'')}" data-detail-uni="${safe(uni)}" ${group?`data-hover-group="${safe(group.id)}" data-hover-uni="${safe(uni)}"`:''}><div class="degree-main">${profileMarker(group,uni)}<div><div class="degree-heading"><button class="degree-title" type="button" data-open-detail="${safe(group?.id||'')}" data-detail-uni="${safe(uni)}"><span data-degree-name>${safe(allCampuses?group.name:g.titulacion)}</span></button><span class="degree-actions">${subjectBook(group,uni)}${favoriteButton(group,uni)}</span></div><div class="degree-subline">${safe(allCampuses?[...new Set(group.offers.map(o=>o.centro).filter(Boolean))].join(' · '):g.centro||'Centro por confirmar')} <span class="dot">·</span>${safe(allCampuses?[...new Set(group.offers.map(o=>o.campus))].join(' · '):g.campus)}</div><div class="minor-tags">${allCampuses?'<span class="interest-caption status-'+window.UniFavorites.status(uni,group.key)+'">'+safe(window.UniFavorites.states[window.UniFavorites.status(uni,group.key)].label)+'</span>':''}${uni==='mondragon'&&g.aviso_admision?pill(g.estado_oferta,'admission-pill'):''}${g.ects?pill(`${num(g.ects)} ECTS`):''}${g.anos?pill(`${num(g.anos)} años`):''}${allCampuses&&group.offers.length>1?pill('Notas / precios: '+g.campus+' · ver todos en la ficha'):''}</div></div></div><div class="note-pair">${isE?noteMini(g,2025)+noteMini(g,2026):`<div class="year-note"><small>1.º · ${safe(priceYear(g,uni))}</small><b>${eur(g.precio_primero,uni==='uned'?2:0)}</b></div><div class="year-note"><small>Total aprox.</small><b>${eur(g.coste_total_est,uni==='uned'?2:0)}</b></div>`}</div><div class="row-links">${link(g.url_grado,'Carrera')}${link(g.url_centro,'Facultad')}${!g.url_grado?link(g.fuente_oferta,'Catálogo'):''}</div></article>`}
 function subjectMatchClass(p,uni=state.uni){return window.UniProfile?.matches(p,uni)?'profile-match'+(p.coeficiente===0.1?' profile-match-low':''):''}
 function coefficientClass(p,uni=state.uni){if(!window.UniProfile?.matches(p,uni))return '';return p.coeficiente===0.1?'low':p.coeficiente===0.2?'high':''}
 function subjectsHTML(group){const sets=pondSets(group);if(!sets.length)return `<div class="mini-alert"><strong>Ponderaciones no verificadas.</strong> No se ha podido asociar este grado con materias del PDF. No implica que ninguna materia pondere.</div>`;
  const doubled=state.uni==='ehu'&&(sets.length>1||group.offers.some(g=>norm(g.tipo).includes('doble')));
  const items=entries=>`<div class="subject-head"><span>Asignatura</span><span>Coeficiente</span></div>${entries.slice().sort((a,b)=>b.coeficiente-a.coeficiente||sortText(a.materia,b.materia)).map(p=>`<div class="subject ${subjectMatchClass(p)}"><span class="subject-name">${window.UniProfile?.matches(p,state.uni)?'<span class="match-label">✓ Tu materia</span>':''}${safe(p.materia)}</span><span class="coeff ${coefficientClass(p)}">${num(p.coeficiente,1)}</span></div>`).join('')}`;
  return `${doubled?'<div class="mini-alert"><strong>Doble grado:</strong> consultar los componentes por separado. La EHU usa la opción de ponderación que resulte más favorable; no se suman todas las materias de ambos.</div>':''}${sets.map(s=>`<div class="subject-group">${doubled?`<h3>${safe(s.id)}</h3>`:''}${items(s.items)}</div>`).join('')}<div class="site-notice">Solo coeficientes 0,1 y 0,2. ${link(state.uni==='upna'?raw.upna.meta.fuente_ponderaciones:raw.ehu.meta.fuentes.ponderaciones_2026,'PDF oficial de parámetros '+(state.uni==='upna'?'UPNA':'EHU'))}</div>`}
 function valueBox(label,value,small){return `<div class="note-box"><span class="year">${safe(label)}</span><b class="${small?'na':''}">${safe(value)}</b></div>`}
 function offeringHTML(g){const {uni}=state,isE=isPublic(uni);return `<div class="campus-offering"><div class="offering-top"><div><h3>${safe(g.campus)}</h3><p>${safe(g.centro)}${g.municipio?' · '+safe(g.municipio):''}${g.sede?' · '+safe(g.sede):''}</p></div><div class="offer-links">${link(g.url_grado,'Web carrera')}${link(g.url_centro,'Web facultad')}${!g.url_grado?link(g.fuente_oferta,'Catálogo de grados'):''}</div></div>
  ${uni==='uned'?'':window.UniOrientation?.seats(uni,g)||''}<div class="offering-data">${isE?valueBox('Nota 2025',typeof g.nota_2025==='number'?num(g.nota_2025,3):g.estado_2025==='Plazas vacantes'?'Plazas vacantes':'No consta',typeof g.nota_2025!=='number')+valueBox('Nota 2026'+(g.fase_nota_2026?' · '+g.fase_nota_2026:''),typeof g.nota_2026==='number'?num(g.nota_2026,3):'No consta',typeof g.nota_2026!=='number'):valueBox('Primer curso · '+priceYear(g),eur(g.precio_primero,uni==='uned'?2:0),g.precio_primero==null)+valueBox('Total estimado a precios '+priceYear(g),eur(g.coste_total_est,uni==='uned'?2:0),g.coste_total_est==null)}</div>
  ${(uni==='uned'||uni==='euneiz')&&g.precio_credito!=null?valueBox('Precio por crédito en primera matrícula',eur(g.precio_credito,2)):''}<div class="offering-info">${g.ects?`<strong>Plan:</strong> ${num(g.ects)} ECTS${g.anos?` en ${num(g.anos)} años`:''}.`:''} </div>${window.UniCompare?`<div class="teaching-details"><div><strong>Idioma de docencia</strong><p>${window.UniCompare.languages(g)}</p></div><div><strong>Prácticas</strong><p>${window.UniCompare.practices(uni,g,degreeKey(g))}</p></div></div>`:''}${!isE&&g.coste_total_est!=null?`<div class="cost-method">${safe(g.metodo_estimacion||(uni==='uned'?'La tarifa de primera matrícula se aplica a los créditos matriculados. Primero se estima con 60 ECTS y el total con los créditos del plan, sin tasas ni repeticiones.':'Estimación por ECTS, manteniendo la tarifa '+priceCourse(uni)+'.'))}</div>`:''}${!isE&&g.precio_primero==null?'<div class="mini-alert">'+safe(g.estado_precio||'No consta un importe publicado para esta variante concreta. No se extrapola el precio de otro programa.')+'</div>':''}${g.observaciones?`<div class="offering-info">${safe(g.observaciones)}</div>`:''}</div>`}
 function renderDetail(){
  const {uni}=state,ds=datasets[uni],group=ds.lookup.get(state.group);if(!group){goBack();return}
  const offers=group.offers.slice().sort((a,b)=>CFG[uni].campuses.indexOf(a.campus)-CFG[uni].campuses.indexOf(b.campus));
  const g=offers[0],isE=isPublic(uni);
  main.innerHTML=`${top(CFG[uni].short,'',isE?'Ficha del grado, ponderaciones y notas de acceso.':'Ficha de grado, campus, facultad y estimación de matrícula.')}
  <div class="detail-title-override"><div class="detail-heading"><h1>${safe(group.name)}</h1>${favoriteButton(group)}</div><div class="detail-tags">${pill(g.rama||'Rama no verificada','teal')}${pill(g.tipo||'Grado')}${g.ects?pill(`${num(g.ects)} ECTS`):''}${g.anos?pill(`${num(g.anos)} años`):''}</div></div>
  ${uni==='mondragon'&&g.aviso_admision?'<div class="mini-alert admission-notice">'+safe(g.aviso_admision)+'</div>':''}<div class="detail-tabs" role="tablist" aria-label="Información de la carrera"><button type="button" id="tab-ficha" role="tab" aria-controls="panel-ficha" aria-selected="${state.detailTab!=='orientation'}" tabindex="${state.detailTab==='orientation'?-1:0}" data-action="detail-tab" data-tab="ficha">Ficha y acceso</button><button type="button" id="tab-orientation" role="tab" aria-controls="panel-orientation" aria-selected="${state.detailTab==='orientation'}" tabindex="${state.detailTab==='orientation'?0:-1}" data-action="detail-tab" data-tab="orientation">¿Qué es?</button></div>
  <section id="panel-orientation" role="tabpanel" aria-labelledby="tab-orientation" ${state.detailTab==='orientation'?'':'hidden'}>${window.UniOrientation?.render(uni,group.key)||''}</section>
  <div id="panel-ficha" role="tabpanel" aria-labelledby="tab-ficha" class="detail-layout" ${state.detailTab==='orientation'?'hidden':''}><div class="detail-main">
    ${isE?`<section class="section-card"><h2>Materias de Bachillerato que ponderan</h2><p>Parámetros oficiales ${uni==='upna'?'UPNA':'EHU'} para 2026–2027: solo asignaturas con coeficientes 0,1 o 0,2.</p>${subjectsHTML(group)}</section>`:`<section class="section-card"><h2>Coste de los estudios</h2><p>El importe de primer curso procede de la tabla publicada ${safe(priceCourse(uni))}. ${uni==='mondragon'?'Mondragon lo identifica como un importe previsto, pendiente de aprobación por el Consejo Rector.':''} El coste total se estima manteniendo los precios actuales por crédito: no es una tarifa vinculante.</p><div class="cost-caveat">Los cursos superiores pueden tener tarifas diferentes. No incluye manutención, alojamiento, becas, inflación ni otras tasas. ${uni==='navarra'?'La Universidad de Navarra anuncia además 95 € en derechos de secretaría.':''}</div></section>`}
    ${isE?'<section class="section-card"><h2>Coste de los estudios</h2><p>Primero y carrera completa: estimaciones de docencia a las tarifas oficiales. Los gastos y supuestos se indican debajo.</p>'+offers.map(o=>window.UniTuition?.render(uni,o)||'').join('')+'</section>':''}<section class="section-card"><h2>Campus, centro ${isE?'y notas de corte':'y precio'}</h2><p>${isE?'Las notas pueden variar entre campus o modalidades; no se asume equivalencia entre fases de admisión.':'Los precios se muestran solo donde se han podido asociar a la titulación exacta.'}</p>${offers.map(offeringHTML).join('')}</section>
    </div><aside class="detail-sidebar"><section class="section-card"><h2>Datos académicos</h2><dl class="fact-grid"><div class="fact wide"><dt>Rama</dt><dd>${safe(g.rama||'No verificada')}</dd></div><div class="fact"><dt>Duración</dt><dd>${g.anos?num(g.anos)+' años':'No verificada'}</dd></div><div class="fact"><dt>Créditos</dt><dd>${g.ects?num(g.ects)+' ECTS':'No verificados'}</dd></div><div class="fact wide"><dt>Modalidad</dt><dd>${safe(g.modalidad||g.modalidad_docente||'Presencial')}</dd></div><div class="fact wide"><dt>Idiomas</dt><dd>${safe(g.idiomas||'Pendientes de verificación')}</dd></div></dl></section>
    <section class="section-card"><h2>Enlaces y fuentes</h2><div class="sources-list">${offers.map(o=>link(o.url_grado,`Carrera · ${o.campus}`)+link(o.url_centro,`Facultad · ${o.campus}`)).join('')}${link(g.fuente_oferta,'Oferta oficial de grados')}${!isE?link(g.fuente_precio,'Precios publicados del primer curso · '+priceCourse(uni)):link(uni==='upna'?raw.upna.meta.fuente_ponderaciones:raw.ehu.meta.fuentes.ponderaciones_2026,'PDF ponderaciones 2026')}${!isE?link(g.fuente_admision,'Admisión y ayudas'):''}</div></section>
    ${isE?`<section class="section-card"><h2>Notas de corte</h2><p>La última nota publicada no garantiza el acceso del siguiente curso. ${uni==='upna'?'Para la UPNA se comparan las últimas listas de admitidos en 2025 y 2026. Las notas de primera lista están en el Excel y JSON.':'Las notas de 2025 y 2026 pueden referirse a fases distintas.'}</p></section>`:uni==='uned'?`<section class="section-card"><h2>Acceso y matrícula UNED</h2><p>Consulta los requisitos de admisión de cada grado. Los exámenes y algunas prácticas pueden requerir asistencia presencial.</p>${link(g.fuente_admision,'Acceso y matrícula UNED')}</section>`:`<section class="section-card"><h2>¿Nota de corte?</h2><p>En estas universidades privadas no se ofrece una nota de corte pública comparable con la adjudicación de plazas de la EHU. Consulta sus requisitos y procedimientos de admisión.</p></section>`}
  </aside></div>`;
  const pageTop=main.querySelector('.page-top h1');if(pageTop)pageTop.remove();
 }
 function popupHTML(group,uni=state.uni){const sets=pondSets(group,uni),status=profileStatus(group,uni),summary=status?`<p class="popover-profile-summary">${profileMarker(group,uni)} ${safe(status.label)}${status.max!==null?' · máximo teórico':' · no implica ausencia de ponderaciones oficiales'}</p>`:'';if(!sets.length)return `<strong>${safe(group.name)}</strong>${summary}<p>Ponderaciones no verificadas para esta titulación; no significa que no existan.</p>`;
  const rows=sets.map(s=>`<div class="popover-group">${sets.length>1?`<strong class="popover-heading">${safe(s.id)}</strong>`:''}${s.items.slice().sort((a,b)=>b.coeficiente-a.coeficiente||sortText(a.materia,b.materia)).map(p=>`<div class="${subjectMatchClass(p,uni)}"><span>${window.UniProfile?.matches(p,uni)?'<span class="match-label">✓ Tu materia</span>':''}${safe(p.materia)}</span><b class="${coefficientClass(p,uni)}">${num(p.coeficiente,1)}</b></div>`).join('')}</div>`).join('');return `<strong>${safe(group.name)}</strong>${summary}<p>Materias que ponderan · ${uni==='upna'?'UPNA':'EHU'} 2026–2027</p><div class="popover-scroll" tabindex="0" aria-label="Asignaturas y coeficientes de ponderación">${rows}</div>`;
 }
 let activeHoverRow=null,hoverCloseTimer=null,mobilePopover=false,popoverOpener=null;
 const popoverBackdrop=document.getElementById('popover-backdrop');
 function hidePopup(restoreFocus=false){if(hoverCloseTimer){clearTimeout(hoverCloseTimer);hoverCloseTimer=null;}const opener=popoverOpener;opener?.setAttribute('aria-expanded','false');activeHoverRow=null;popoverOpener=null;mobilePopover=false;popup.hidden=true;popup.innerHTML='';popup.setAttribute('role','tooltip');popup.removeAttribute('aria-modal');popoverBackdrop.hidden=true;if(restoreFocus===true&&opener?.isConnected)opener.focus();}
 function schedulePopupClose(){if(mobilePopover)return;if(hoverCloseTimer)clearTimeout(hoverCloseTimer);hoverCloseTimer=setTimeout(hidePopup,260)}
 function showPopup(target,mobile=false){const container=target?.closest('[data-hover-group]'),uni=mobile?target?.dataset.bookUni:container?.dataset.hoverUni||state.uni,id=mobile?target?.dataset.subjectBook:container?.dataset.hoverGroup;if(!isPublic(uni)||!id)return;const group=datasets[uni].lookup.get(id);if(!group)return;hidePopup();activeHoverRow=target;mobilePopover=mobile;popoverOpener=mobile?target:null;if(mobile)target.setAttribute('aria-expanded','true');popup.innerHTML=(mobile?'<button type="button" class="popover-close" data-popover-close aria-label="Cerrar ponderaciones">×</button>':'')+popupHTML(group,uni);popup.setAttribute('role',mobile?'dialog':'tooltip');popup.setAttribute('aria-label','Ponderaciones de '+group.name);if(mobile)popup.setAttribute('aria-modal','true');popoverBackdrop.hidden=!mobile;popup.hidden=false;const w=Math.min(365,window.innerWidth-24);popup.style.width=w+'px';popup.style.left=Math.max(12,(window.innerWidth-w)/2)+'px';const height=popup.getBoundingClientRect().height;popup.style.top=Math.max(12,(window.innerHeight-height)/2)+'px';if(mobile)popup.querySelector('[data-popover-close]')?.focus();}
 function trackView(){
  const group=state.screen==='detail'?datasets[state.uni]?.lookup.get(state.group):null;
  window.UniAnalytics?.view({screen:state.screen,uni:state.screen==='portal'||state.screen==='favorites'?null:state.uni,
   degree:group?.name,segment:group?.key||({campus:state.campus,rama:state.rama,subject:state.materia})[state.screen],
   tab:group?state.detailTab:null,title:group?.name||CFG[state.uni]?.name||state.screen});
 }
 function render(){const label=document.getElementById('active-university-label');label.textContent=state.screen==='favorites'?'Carreras seleccionadas':state.uni?CFG[state.uni].short:(datasets.euneiz&&datasets.uned?'Siete universidades':'Cinco universidades');hidePopup();if(state.screen==='portal')renderPortal();else if(state.screen==='favorites')renderFavorites();else if(state.screen==='compare')renderCompare();else if(state.screen==='university')renderUniversity();else if(['campus','rama','subject'].includes(state.screen))renderList();else if(state.screen==='detail')renderDetail();trackView();}
 function openDetail(id,uni=state.uni){if(!datasets[uni]?.lookup.has(id))return;go('detail',{uni,group:id,detailTab:'ficha'})}
 function openCampus(c){if(!CFG[state.uni].campuses.includes(c))return;go('campus',{campus:c,facultad:'',materia:'',q:'',sort:'name',statusFilter:'all'})}
 function openRama(r){if(!RAMAS.includes(r))return;go('rama',{rama:r,campus:'',facultad:'',materia:'',q:'',sort:'name',statusFilter:'all'})}
 function openSubject(m){if(!materias().includes(m))return;go('subject',{materia:m,campus:'',facultad:'',q:'',sort:'name',statusFilter:'all'})}
 function resetFilters(){state.q='';state.facultad='';state.materia=state.screen==='subject'?state.materia:'';state.sort='name';state.statusFilter='all';if(state.screen!=='campus')state.campus='';renderList()}
 document.addEventListener('click',e=>{
  if(e.target.closest('#selection-dialog,#help-dialog'))return;
  if(e.target.closest('[data-popover-close]')){hidePopup(true);return;}
  const book=e.target.closest('[data-subject-book]');if(book){showPopup(book,true);return;}
  if(e.target.closest('a')||popup.contains(e.target))return;
  const favorite=e.target.closest('[data-favorite]');if(favorite){const uni=favorite.dataset.favoriteUni,group=datasets[uni]?.lookup.get(favorite.dataset.favorite);if(group){hidePopup();window.UniSelectionDialog.open({uni,key:group.key,name:group.name},favorite);}return;}
  const b=e.target.closest('[data-uni],[data-open-campus],[data-open-rama],[data-open-detail],[data-action],#brand-home');if(!b){if(state.screen==='university'&&!e.target.closest('#search-wrap')){const el=document.getElementById('search-suggestions');if(el)el.hidden=true;}return}
  if(b.id==='brand-home'){if(state.screen!=='portal')go('portal',initial());}
  else if(b.dataset.uni)chooseUni(b.dataset.uni);
  else if(b.dataset.openCampus)openCampus(b.dataset.openCampus);
  else if(b.dataset.openRama)openRama(b.dataset.openRama);
  else if(b.dataset.openDetail)openDetail(b.dataset.openDetail,b.dataset.detailUni||state.uni);
  else if(b.dataset.action==='detail-tab'){state.detailTab=b.dataset.tab==='orientation'?'orientation':'ficha';saveHistory();renderDetail();trackView();document.getElementById('tab-'+state.detailTab)?.focus();}
  else if(b.dataset.action==='back')goBack();
  else if(b.dataset.action==='compare')go('compare',{uni:null,comparison:null});
  else if(b.dataset.action==='favorites')go('favorites',{uni:null,shortlistFilter:'all'});
  else if(b.dataset.action==='export-favorites'){exportFavorites();window.UniAnalytics?.emit('favorites_export',{export_format:'csv'});}
  else if(b.dataset.action==='print-favorites'){window.UniAnalytics?.emit('favorites_export',{export_format:'pdf'});window.print();}
  else if(b.dataset.action==='search-subject'){const m=document.getElementById('home-materia')?.value;if(m)openSubject(m)}
  else if(b.dataset.action==='reset-filters')resetFilters();
 });
 let searchTimer;
 document.addEventListener('input',e=>{if(e.target.id==='degree-search'){
  updateSuggestions();
  clearTimeout(searchTimer);
  const uni=state.uni;
  if(norm(e.target.value).length>=3)searchTimer=setTimeout(()=>{
   if(state.screen==='university'&&state.uni===uni)window.UniAnalytics?.emit('university_search',{university:uni});
  },650);
 }if(e.target.id==='list-query'){state.q=e.target.value;updateList()}});
 document.addEventListener('change',e=>{
  if(e.target.id==='selection-filter'){if(state.screen==='favorites'){state.shortlistFilter=e.target.value;saveHistory();renderFavorites();document.getElementById('selection-filter')?.focus();}else{state.statusFilter=e.target.value;updateList();}return;}
  if(e.target.id==='faculty-filter'){state.facultad=e.target.value;updateList()}
  if(e.target.id==='campus-filter'){state.campus=e.target.value;updateList()}
  if(e.target.id==='materia-filter'){state.materia=e.target.value;updateList()}
  if(e.target.id==='sort-by'){state.sort=e.target.value;updateList()}
 });
 document.addEventListener('keydown',e=>{
  if(document.getElementById('selection-dialog')?.open||document.getElementById('help-dialog')?.open)return;
  if(e.key==='Escape'){hidePopup(true);const sug=document.getElementById('search-suggestions');if(sug)sug.hidden=true}
  if(e.target.matches?.('[data-action="detail-tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();state.detailTab=e.key==='Home'?'ficha':e.key==='End'?'orientation':state.detailTab==='orientation'?'ficha':'orientation';saveHistory();renderDetail();trackView();document.getElementById('tab-'+state.detailTab)?.focus();return;}
  if(e.target.id!=='degree-search')return;const el=document.getElementById('search-suggestions');if(!el||el.hidden)return;const opts=[...el.querySelectorAll('[data-open-detail]')];if(!opts.length)return;const idx=opts.findIndex(o=>o.classList.contains('active'));
  if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const next=(idx+(e.key==='ArrowDown'?1:-1)+opts.length)%opts.length;opts.forEach((o,i)=>{o.classList.toggle('active',i===next);o.setAttribute('aria-selected',String(i===next))});opts[next].scrollIntoView({block:'nearest'})}
  if(e.key==='Enter'){e.preventDefault();openDetail(opts[idx>=0?idx:0].dataset.openDetail)}
 });
 document.addEventListener('pointerover',e=>{if(mobilePopover||compactPopover()||e.pointerType==='touch')return;if(popup.contains(e.target)){if(hoverCloseTimer)clearTimeout(hoverCloseTimer);hoverCloseTimer=null;return;}const title=e.target.closest('[data-degree-name]');if(title){if(hoverCloseTimer)clearTimeout(hoverCloseTimer);hoverCloseTimer=null;if(!title.contains(e.relatedTarget))showPopup(title);}});
 function hidePopupIfExited(e){if(mobilePopover)return;const title=e.target.closest('[data-degree-name]'),next=e.relatedTarget;if(title===activeHoverRow&&title&&!title.contains(next)&&!popup.contains(next))schedulePopupClose();else if(popup.contains(e.target)&&!popup.contains(next)&&!(activeHoverRow&&activeHoverRow.contains(next)))schedulePopupClose();}
 document.addEventListener('pointerout',hidePopupIfExited);
 document.addEventListener('keydown',e=>{if(document.getElementById('help-dialog')?.open||!mobilePopover||e.key!=='Tab')return;const focusable=[...popup.querySelectorAll('button,[tabindex="0"],a[href]')];if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
 window.addEventListener('scroll',()=>{if(!mobilePopover)hidePopup();},{passive:true});window.addEventListener('resize',()=>hidePopup());
 if(Object.keys(CFG).some(uni=>!raw[uni]?.grados)){main.innerHTML='<div class="empty-panel"><b>No se han cargado los datos.</b>Comprueba los archivos de la carpeta data/ y su publicación.</div>';return}
 window.addEventListener('uni-profile-change',()=>render());
 window.addEventListener('uni-favorites-change',refreshFavorites);
 window.addEventListener('uni-selection-saved',e=>favoriteNotice(e.detail.name+' · '+window.UniFavorites.states[e.detail.status].label));
 render();
})();
